INSERT INTO news (slug, title, excerpt, blocks, coverImageUrl, categoryId, date, externalLink, location, tags, featured, status, createdAt, updatedAt, publishedAt)
VALUES ('returning-to-new-swan-theatre-festival-in-2026', 'Returning to New Swan Theatre Festival in 2026', 'Scenic designer Brandon PT Davis returns to the New Swan Shakespeare Festival for the 2026 season, creating a single transformative scenic environment that supports two productions set in contrasting American eras—from a 1950s Southern California surf town to the stark landscape of the Dust Bowl.', '[{"type":"text","content":"Scenic designer Brandon PT Davis returns to the New Swan Shakespeare Festival for the 2026 season, bringing his narrative-driven design approach to a repertory lineup spanning two distinct American eras. Davis will design the scenery for both The Merry Wives of Windsor Cove, a musical reimagining set in a rock-and-roll 1950s Southern California surf town, and a stark, Dust Bowl–era staging of Romeo and Juliet."},{"type":"text","content":"Running July 7 through August 30, the season challenges Davis to create a single architectural gesture capable of transforming from a sun-drenched beach party into a landscape of scarcity and survival, all within the intimacy of the festival''s 130-seat mini-Elizabethan theatre. Building on his previous collaborations with New Swan, Davis''s designs will support the distinct directorial visions of Eli Simon and Rachael VanWormer, grounding the alternating productions in their specific historical contexts."},{"type":"text","content":"Merry Wives will embrace the color and energy of mid-century surf culture, while Romeo and Juliet strips the stage back to reflect the harsh realities of the Great Depression. Tickets for the 2026 season go on sale in April, with Davis''s transformative scenery providing the visual foundation for a summer of comedy, tragedy, and live music under the stars."}]', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663337866878/rgFRWjllpmhIfvKG.webp', 1, '2025-11-28', 'https://newswanshakespeare.com/', 'New Swan Theatre Festival ', 'NewSwanShakespeareFestival, California, ScenicDeisgn, Brandon PT Davis scenic design, New Swan Shakespeare Festival 2026', 1, 'published', NOW(), NOW(), '2025-11-28');

INSERT INTO news (slug, title, excerpt, blocks, coverImageUrl, categoryId, date, externalLink, location, tags, featured, status, createdAt, updatedAt, publishedAt)
VALUES ('million-dollar-quartet-orange-curtain-review', 'The Orange Curtain Review Praises Million Dollar Quartet at South Coast Repertory', 'The Orange Curtain Review praised the South Coast Repertory production of Million Dollar Quartet, highlighting the scenic design by Brandon PT Davis and Kris Stone as a key contributor to the production''s immersive energy and historical authenticity.', '[{"type":"text","content":"The Orange Curtain Review published a glowing review of South Coast Repertory''s production of Million Dollar Quartet, which ran from September 13 through October 12, 2025, in the Julianne Argyros Stage. The review praised the production''s immersive energy, dynamic performances, and its ability to transport audiences to the legendary 1956 recording session at Sun Studio in Memphis, Tennessee."},{"type":"text","content":"Scenic designers Brandon PT Davis and Kris Stone were specifically highlighted for their work creating an authentic and functional environment that supported the production''s storytelling. The review noted: "The scenic design by Brandon PT Davis and Kris Stone is a standout, capturing the gritty authenticity of Sun Studio while allowing the performers to command the space with ease.""},{"type":"text","content":"The design team''s work contributed to a production that felt both historically grounded and theatrically alive, reinforcing the role of scenery as an active partner in musical storytelling. Having the scenic work recognized within such a high-energy, music-driven production was a meaningful moment in Davis''s career, particularly as his debut at South Coast Repertory."}]', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663337866878/UqtGxQOFTFXHmRrW.webp', 2, '2025-10-13', 'https://theorangecurtainreview.com/2025/10/13/million-dollar-quartet-at-south-coast-repertory/', 'South Coast Rep - Costa Mesa, CA', 'Reviews, South Coast Rep, Million Dollar Quartet, Scenic Design, Million Dollar Quartet SCR', 0, 'published', NOW(), NOW(), '2025-10-13');

INSERT INTO news (slug, title, excerpt, blocks, coverImageUrl, categoryId, date, externalLink, location, tags, featured, status, createdAt, updatedAt, publishedAt)
VALUES ('making-my-scr-debut', 'Making My SCR Debut: Million Dollar Quartet (2025)', 'Brandon PT Davis makes his South Coast Repertory debut as co-scenic designer for Million Dollar Quartet, collaborating with Kris Stone to recreate the legendary 1956 Sun Studio recording session that brought together Elvis Presley, Johnny Cash, Jerry Lee Lewis, and Carl Perkins.', '[{"type":"text","content":"August 29, 2025 — I'm excited to share that I'll be making my South Coast Repertory debut this fall as the co-scenic designer for Million Dollar Quartet, running September 13–October 12, 2025, in the Julianne Argyros Stage. I'll be collaborating with Kris Stone to design the scenic environment for this high-energy musical, which recreates the legendary 1956 recording session at Sun Studio in Memphis, Tennessee—the moment when Elvis Presley, Johnny Cash, Jerry Lee Lewis, and Carl Perkins came together for an impromptu jam session that would become one of the most iconic moments in rock and roll history."},{"type":"text","content":"Directed by David Ivers, the production will bring the raw energy, spontaneity, and musical brilliance of that night to life. Designing a space that honors the historical authenticity of Sun Studio while supporting the theatrical demands of live performance—and also finding moments of humor and intimacy—presents a thrilling creative challenge."},{"type":"text","content":"Davis extends his gratitude to David Ivers, Suzanne Appel, Kim Martin-Cotten, James Moye, and the entire South Coast Repertory company for their trust and collaboration. He looks forward to sharing the world of Million Dollar Quartet with audiences this fall."}]', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663337866878/jtjFvDSgIJMjqsVA.hUNvfDTcMm2IhC_iK0V-s8Jo0sL4pnl-R_VYHZMmVoQ', 1, '2025-08-29', 'https://www.scr.org/scr-blog/posts/meet-the-creative-team-of-million-dollar-quartet', 'South Coast Rep - Costa Mesa, CA', 'SCR, South Coast Rep, Million Dollar Quartet, Co-Design Debut, Musical Theatre', 0, 'published', NOW(), NOW(), '2025-08-29');

INSERT INTO news (slug, title, excerpt, blocks, coverImageUrl, categoryId, date, externalLink, location, tags, featured, status, createdAt, updatedAt, publishedAt)
VALUES ('assisting-the-play-that-goes-wrong', 'Assisting Tom Buderwitz on The Play That Goes Wrong at Seattle Rep', 'Serving as Assistant Scenic Designer to Tom Buderwitz, Brandon PT Davis contributed to the Seattle Repertory Theatre production of The Play That Goes Wrong, supporting the creation of meticulously engineered comedic chaos in the Bagley Wright Theater during the 2025 season.', '[{"type":"text","content":"The Play That Goes Wrong opened at Seattle Repertory Theatre on August 28, 2025, and I was proud to serve as Assistant Scenic Designer to Tom Buderwitz, a longtime mentor whose guidance I deeply value. The production runs in the Bagley Wright Theater through September 28, 2025, and it has been a pleasure to contribute behind the scenes on what promises to be a riotous and meticulously crafted comedy."},{"type":"text","content":"The assistant role on The Play That Goes Wrong is both hands-on and illuminating. My work has spanned everything from model plotting to live adjustments, collaborating closely with Tom as the design balances precise technical execution with intentional visual chaos. His sharp eye for comedic mischief—where everything appears to collapse while remaining structurally sound—offers a master class in how comedy and craft intersect."},{"type":"text","content":"Working alongside Tom reinforces a core truth of scenic design: it is never just about scenery. It is collaborative, energetic, and responsive, supporting performers through controlled disorder with clarity and calm. Being part of this process has been a powerful reminder of how design functions as an active partner in storytelling, especially when everything goes wrong in exactly the right ways."}]', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663337866878/xKLAahvHsMUpJjvt.8-0if8P2z4_fPAHkkXrQm6U0XN9zPoBrGv_NXdYtqV4', 4, '2025-08-28', 'https://www.seattlerep.org/plays/202526-season/the-play-that-goes-wrong', 'Seattle Rep', 'The Play That Goes Wrong, Tom Buderwitz, Assistant Scenic Design, The Play That Goes Wrong Scenic Design, Seattle Repertory Theatre Productions', 0, 'published', NOW(), NOW(), '2025-08-28');

INSERT INTO news (slug, title, excerpt, blocks, coverImageUrl, categoryId, date, externalLink, location, tags, featured, status, createdAt, updatedAt, publishedAt)
VALUES ('40-productions-at-okoboji-summer-theatre', '40 Productions at Okoboji Summer Theatre', 'Marking his 40th production and 15th season at Okoboji Summer Theatre, scenic designer Brandon PT Davis reflects on the mentorship, collaboration, and community that have defined his long-standing relationship with the company.', '[{"type":"text","content":"August 5, 2023 marked the opening of my 40th production at Okoboji Summer Theatre—a milestone that still feels surreal to write. I was 38 at the time, and somehow it had become my 15th season with the company. Time compresses when you think back on the shows, the late nights, and the many students and artists I've had the privilege to work alongside."},{"type":"text","content":"Two people have been constants every single summer: Michael Burke, Director of Production, and Ruth Ann Burke, Executive Director. They are the anchors of this theatre, and working with them year after year has shaped not only my career, but my understanding of what summer stock can be at its best—rigorous, communal, and deeply human."},{"type":"text","content":"Forty productions is a number I never could have imagined when I first arrived. More than the milestone itself, I'm grateful for the friendships, mentorship, and sense of community that Okoboji has built around the act of making theatre."}]', 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663337866878/RuCtVtvakPaJIwKp.HzN5DV0m3JHhE3awWjokR11cm4Xt_U6OBAbrJs5PPSM', 3, '2025-08-06', NULL, 'Okoboji Summer Theatre', 'Okoboji Summer Theatre, Career Milestone, Summer Stock, Okoboji Summer Theatre scenic design, Michael Burke director', 0, 'published', NOW(), NOW(), '2025-08-06');

